import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int T = sc.nextInt();
        sc.nextLine();

        for (int tc = 1; tc <= T; tc++) {
            String line = sc.nextLine();

            Deque<Character> stack = new ArrayDeque<>();

            boolean singleQuote = false;
            boolean doubleQuote = false;
            boolean isValid = true;

            for (char ch : line.toCharArray()) {

                // 작은따옴표 시작/종료
                if (ch == '\'' && !doubleQuote) {
                    singleQuote = !singleQuote;
                    continue;
                }

                // 큰따옴표 시작/종료
                if (ch == '"' && !singleQuote) {
                    doubleQuote = !doubleQuote;
                    continue;
                }

                // 따옴표 내부의 괄호는 무시
                if (singleQuote || doubleQuote) {
                    continue;
                }

                // 여는 괄호
                if (ch == '(' || ch == '{') {
                    stack.push(ch);
                }

                // 닫는 소괄호
                else if (ch == ')') {
                    if (stack.isEmpty() || stack.peek() != '(') {
                        isValid = false;
                        break;
                    }
                    stack.pop();
                }

                // 닫는 중괄호
                else if (ch == '}') {
                    if (stack.isEmpty() || stack.peek() != '{') {
                        isValid = false;
                        break;
                    }
                    stack.pop();
                }
            }

            if (!stack.isEmpty()) {
                isValid = false;
            }

            System.out.println("#" + tc + " " + (isValid ? 1 : 0));
        }
    }
}

package solution;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Solution {
	/*
	 * 상자들이 한줄.
	 * 맞붙어 있는 두 상자에 적힌 글자가 같으면, 같이 내려감.
	 * 나머지들은 붙게됨.
	 * 묶음처리 끝난뒤 남은 상자갯수.
	 */

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		for(int times=1; times<=T;times++) {
			Deque<Character> stack = new ArrayDeque<Character>();
			String boxes = sc.next();

			for(char x : boxes.toCharArray()) {
				if (!stack.isEmpty() && stack.peek() == x) {
					stack.pop();
				}else {
					stack.push(x);
				}
			}
			System.out.printf("#%d %d%n",times, stack.size());

		}
	}


}

package solution;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Scanner;

public class Solution {
	/*
	 * 광고판 N개. 누적 조회수.
	 * M번 회전했을때 정면 광고판?
	 */

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int T = sc.nextInt();
		for(int times=1; times<=T;times++) {
			int N = sc.nextInt(); //N은 광고판개수
			int M = sc.nextInt(); //M은 총 회전횟수

			int[] nums = new int[N];
			for(int i=0; i<N;i++) {
				nums[i] = sc.nextInt();
			}

			int result = M % N;
			System.out.printf("#%d %d%n",times, nums[result]);

		}
	}


}
